const std=@import("std");const M=@import("experimental/hydration_lifecycle_core.zig");const P=@import("simulation/microbes.zig");
fn parent()M.Cohort{return .{.biomass=0.4,.support_mass=0.1,.organization=0.25,.retention_allocation=0.25,.stored_water=0.2,.reproduction_credit=0.3,.lineage=1};}
fn total(cells:[]const M.Cell)f64{var w:f64=0;for(cells)|c|w+=M.waterTotal(c);return w;}
test "funded same and crosscell daughter water inheritance no duplication"{for([_]bool{false,true})|same|{var cells=[_]M.Cell{M.initialized(17),M.initialized(31)};cells[0].cohorts[0]=parent();var stats:M.Stats=.{.next_lineage=2};const w=total(&cells);const target=if(same)@as(usize,0) else 1;try std.testing.expect(M.reproduce(&cells[0],0,&cells[target],&stats,true));try std.testing.expectApproxEqAbs(w,total(&cells),1e-15);const child=cells[target].cohorts[if(same)@as(usize,1) else 0];try std.testing.expectEqual(@as(f32,0.25),child.retention_allocation);try std.testing.expect(child.stored_water>0 and child.stored_water<=M.waterCapacity(child));try std.testing.expect(cells[0].cohorts[0].stored_water<0.2);}}
test "lowered capacity and cutoff death release owned water before reuse"{var c=M.initialized(1);c.cohorts[0]=parent();const w=M.waterTotal(c);c.cohorts[0].retention_allocation=0.01;M.settleWater(&c);try std.testing.expect(c.liquid_return>0);try std.testing.expectApproxEqAbs(w,M.waterTotal(c),1e-15);c.cohorts[0].biomass=0.001;c.cohorts[0].support_mass=0.0001;_=M.step(&c,.{.temperature=300,.depth_km=0,.light=0,.carbon_available=0,.oxygen_carbon_capacity=0},3600);try std.testing.expectEqual(@as(f64,0),c.cohorts[0].stored_water);try std.testing.expectEqual(@as(f32,0),c.cohorts[0].biomass);try std.testing.expectApproxEqAbs(w,M.waterTotal(c),1e-15);}
test "gross grazing releases prey water no hydration bonus"{var c=M.initialized(1);c.cohorts[0]=parent();c.cohorts[1]=.{.biomass=0.2,.feeding=1,.lineage=2};const w=M.waterTotal(c);const f=M.graze(&c,0.2,10);try std.testing.expect(f.consumed>0);try std.testing.expect(c.liquid_return>0 and c.cohorts[0].stored_water<0.2);try std.testing.expectEqual(@as(f64,0),c.cohorts[1].stored_water);try std.testing.expectApproxEqAbs(w,M.waterTotal(c),1e-15);}
test "zero allocation preserves actual original reproduction six draws and old fields"{var a=M.initialized(123);var b=P.initialized(123);a.cohorts[0]=parent();a.cohorts[0].retention_allocation=0;a.cohorts[0].stored_water=0;inline for(std.meta.fields(P.Cohort))|f|@field(b.cohorts[0],f.name)=@field(a.cohorts[0],f.name);var sa:M.Stats=.{.next_lineage=2};var sb:P.Stats=.{.next_lineage=2};try std.testing.expectEqual(P.reproduce(&b,0,&b,&sb,true),M.reproduce(&a,0,&a,&sa,true));try std.testing.expectEqual(a.rng,b.rng);for(0..4)|i|{inline for(std.meta.fields(P.Cohort))|f|try std.testing.expectEqual(@field(b.cohorts[i],f.name),@field(a.cohorts[i],f.name));}try std.testing.expectEqual(@as(f64,0),M.waterTotal(a));}
test "support shedding autonomous move returns all water at source"{var cells=[_]M.Cell{M.initialized(7),M.initialized(9)};cells[0].cohorts[0]=parent();cells[0].cohorts[0].feeding=1;cells[0].cohorts[0].mobility=1;cells[1].cohorts[0]=.{.biomass=0.2,.lineage=2};const w=total(&cells);const env=M.Environment{.temperature=300,.depth_km=0.002,.light=1,.carbon_available=10,.oxygen_carbon_capacity=10};const neighbors=[_]M.Neighbor{.{.index=1,.environment=env}};const moved=M.relocate(&cells,0,0,env,&neighbors,100*86400,86400);try std.testing.expect(moved.moved);try std.testing.expectEqual(@as(f64,0.2),cells[0].liquid_return);try std.testing.expectEqual(@as(f64,0),cells[1].cohorts[1].stored_water);try std.testing.expectApproxEqAbs(w,total(&cells),1e-15);}
test "escrow-only empty cell remains valid and failed birth atomic"{var c=M.initialized(1);c.liquid_return=0.1;c.vapor_return=0.2;try std.testing.expect(M.validCell(c,2));const before=c;var stats:M.Stats=.{.next_lineage=2};try std.testing.expect(!M.reproduce(&c,0,&c,&stats,true));try std.testing.expectEqualDeep(before,c);c.cohorts[0].stored_water=0.1;try std.testing.expect(!M.validCell(c,2));M.settleWater(&c);try std.testing.expect(M.validCell(c,2));try std.testing.expectApproxEqAbs(@as(f64,0.4),M.waterTotal(c),1e-15);}
test "funded propagule inherits allocation and owned water"{var a=M.initialized(1);var b=M.initialized(2);a.cohorts[0]=parent();var stats:M.Stats=.{.next_lineage=2};const w=M.waterTotal(a)+M.waterTotal(b);try std.testing.expect(M.propagate(&a,0,&b,&stats));try std.testing.expect(b.cohorts[0].stored_water>0);try std.testing.expectEqual(@as(f32,0.25),b.cohorts[0].retention_allocation);try std.testing.expectApproxEqAbs(w,M.waterTotal(a)+M.waterTotal(b),1e-15);}
test "disabled step matches all production old fields flux and pools"{var a=M.initialized(123);var b=P.initialized(123);a.cohorts[0]=parent();a.cohorts[0].retention_allocation=0;a.cohorts[0].stored_water=0;a.cohorts[1]=.{.biomass=0.1,.feeding=0.7,.lineage=2};for(0..4)|i|{inline for(std.meta.fields(P.Cohort))|f|@field(b.cohorts[i],f.name)=@field(a.cohorts[i],f.name);}for(0..120)|tick|{const depth:f32=if(tick<60)0.002 else 0;const x=M.step(&a,.{.temperature=300,.depth_km=depth,.light=1,.carbon_available=10,.oxygen_carbon_capacity=10},1440);const y=P.step(&b,.{.temperature=300,.depth_km=depth,.light=1,.carbon_available=10,.oxygen_carbon_capacity=10},1440);inline for(std.meta.fields(P.Flux))|f|try std.testing.expectEqual(@field(y,f.name),@field(x,f.name));for(0..4)|i|{inline for(std.meta.fields(P.Cohort))|f|try std.testing.expectEqual(@field(b.cohorts[i],f.name),@field(a.cohorts[i],f.name));}try std.testing.expectEqual(a.nutrient,b.nutrient);try std.testing.expectEqual(a.detritus,b.detritus);try std.testing.expectEqual(a.rng,b.rng);try std.testing.expectEqual(@as(f64,0),M.waterTotal(a));}}
